INSERT INTO `posts` VALUES(1, 'GK', 'Yay! Febulous is live!', '', 'Now that Febulous is live, we will need the help of each of our Users to keep it up and running. \n\nPublish your posts, react to other''s posts, keep your profile up to date, chat with other Users and do much more things to keep yourself active on Febulous.\n \nPlease do pray that Febulous becomes a success and guess what? \n\nThis is not the end, it''s just the beginning!', 7, '2016-09-10 10:16:54', 'Yes', 'Yes');
INSERT INTO `posts` VALUES(2, 'Materials', 'Check out my Essay on Life!', '', 'lifeasitshouldbe.docx', 7, '2016-09-10 10:21:01', 'Yes', 'Yes');
INSERT INTO `posts` VALUES(3, 'Materials', 'Check out my Essay on Education!', '', 'education.docx', 7, '2016-09-10 10:22:10', 'Yes', 'Yes');
INSERT INTO `posts` VALUES(4, 'GK', 'A Guide to use Febulous!', '', 'Considering the fact that Febulous has a unique strategy of connecting people through an Android Application, I as it''s developer shall take responsibility of guiding all the Users on how to use Febulous through the next few posts.\n\nThe next few posts will include a guide on using your :\n\n- Homepage\n- Profile Page\n- Messenger\n- Notifications\n- Contact Page\n- Dashboard\n- Publish/Post Page \n\nPlease do post your queries if any through the comments section of each post.', 7, '2016-09-10 10:33:07', 'Yes', 'Yes');
INSERT INTO `posts` VALUES(5, 'GK', 'Guide to use your Homepage', '', 'You have five things that you may do while using your Homepage and they include :\n\n- Viewing Posts, Scrolling through Posts and Opening Posts by clicking on them \n\n- Searching for the already loaded posts through the search bar\n\n- Using the Profile options by clicking the button on the left side top corner of your Homepage to select what you want to do with your Profile related entities.\n\n- Using the Filter options by clicking the button on the right side top corner of your Homepage to choose what type of posts must occur on your Homepage temporarily.\nNote : If you want to revert to your original form, you should choose the first option in all the filters.\n\n- Click on the Dashboard button to go to your Dashboard to view topic related posts and to Publish such Posts in each topic.', 7, '2016-09-10 10:45:46', 'No', 'No');
INSERT INTO `posts` VALUES(6, 'Ideas', 'astral travel', '', 'mostly based on astro ', 24, '2016-10-05 20:27:50', 'No', 'No');

